def add_database_row(db_title, properties, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0284000" if __import__("os").path.isdir("./environment_mix/0284000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_usage_store():
        usage = _load("usage_log.json")
        if not isinstance(usage, dict):
            usage = {}
        if "requests" not in usage or not isinstance(usage.get("requests"), list):
            usage["requests"] = []
        if "counters" not in usage or not isinstance(usage.get("counters"), dict):
            usage["counters"] = {}
        if "total_requests" not in usage["counters"]:
            usage["counters"]["total_requests"] = 0
        return usage

    def _log_and_maybe_limit(status, started, endpoint, meta=None):
        usage = _ensure_usage_store()
        now_ts = time.time()
        # simple per-endpoint rate limit: 120 req/min
        window_s = 60
        limit = 120
        recent = 0
        for r in reversed(usage["requests"][-1000:]):
            try:
                if r.get("endpoint") == endpoint and (now_ts - float(r.get("ts_unix", 0))) <= window_s:
                    recent += 1
                    if recent >= limit:
                        break
            except Exception:
                continue
        if recent >= limit and status == "blocked_rate_limit":
            usage["counters"]["total_requests"] += 1
            usage["requests"].append(
                {
                    "id": "req_" + uuid.uuid4().hex,
                    "endpoint": endpoint,
                    "status": "RATE_LIMIT",
                    "ts": _now(),
                    "ts_unix": now_ts,
                    "latency_ms": int((time.time() - started) * 1000),
                    "meta": meta or {},
                }
            )
            _save("usage_log.json", usage)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    started = time.time()
    endpoint = "add_database_row"

    # Validate inputs
    if not isinstance(db_title, str) or not db_title.strip():
        usage = _ensure_usage_store()
        usage["counters"]["total_requests"] += 1
        usage["requests"].append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": "VALIDATION_ERROR",
                "ts": _now(),
                "ts_unix": time.time(),
                "latency_ms": int((time.time() - started) * 1000),
            }
        )
        _save("usage_log.json", usage)
        return _err("VALIDATION_ERROR", "db_title is required and must be a non-empty string.")
    if not isinstance(properties, dict):
        usage = _ensure_usage_store()
        usage["counters"]["total_requests"] += 1
        usage["requests"].append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": "VALIDATION_ERROR",
                "ts": _now(),
                "ts_unix": time.time(),
                "latency_ms": int((time.time() - started) * 1000),
            }
        )
        _save("usage_log.json", usage)
        return _err("VALIDATION_ERROR", "properties must be an object (dict).")

    # Load databases
    dbs = _load("notion_databases.json")
    if not isinstance(dbs, list):
        dbs = []

    title = db_title.strip()

    matches = [d for d in dbs if isinstance(d, dict) and d.get("title") == title]
    if len(matches) == 0:
        usage = _ensure_usage_store()
        usage["counters"]["total_requests"] += 1
        usage["requests"].append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": "NOT_FOUND",
                "ts": _now(),
                "ts_unix": time.time(),
                "latency_ms": int((time.time() - started) * 1000),
                "meta": {"db_title": title},
            }
        )
        _save("usage_log.json", usage)
        return _err("NOT_FOUND", "Database not found.", db_title=title)
    if len(matches) > 1:
        usage = _ensure_usage_store()
        usage["counters"]["total_requests"] += 1
        usage["requests"].append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": "CONFLICT",
                "ts": _now(),
                "ts_unix": time.time(),
                "latency_ms": int((time.time() - started) * 1000),
                "meta": {"db_title": title, "matches": len(matches)},
            }
        )
        _save("usage_log.json", usage)
        return _err("CONFLICT", "Database title is ambiguous.", db_title=title, matches=len(matches))

    db = matches[0]
    schema = db.get("schema")
    if not isinstance(schema, dict):
        schema = {}
        db["schema"] = schema
    if "rows" not in db or not isinstance(db.get("rows"), list):
        db["rows"] = []

    # Validate properties against schema: unknown keys rejected, basic type checks where possible
    allowed = set(schema.keys())
    unknown = [k for k in properties.keys() if k not in allowed]
    if unknown:
        usage = _ensure_usage_store()
        usage["counters"]["total_requests"] += 1
        usage["requests"].append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": "VALIDATION_ERROR",
                "ts": _now(),
                "ts_unix": time.time(),
                "latency_ms": int((time.time() - started) * 1000),
                "meta": {"unknown_properties": unknown},
            }
        )
        _save("usage_log.json", usage)
        return _err("VALIDATION_ERROR", "Unknown properties provided.", unknown_properties=unknown)

    def _type_ok(expected, value):
        if expected is None:
            return True
        if not isinstance(expected, str):
            return True
        t = expected.lower()
        if t in ("text", "string", "title", "rich_text", "email", "url", "date"):
            return value is None or isinstance(value, str)
        if t in ("number", "float", "double"):
            return value is None or isinstance(value, (int, float)) and not isinstance(value, bool)
        if t in ("integer", "int"):
            return value is None or (isinstance(value, int) and not isinstance(value, bool))
        if t in ("checkbox", "boolean", "bool"):
            return value is None or isinstance(value, bool)
        return True

    bad = {}
    for k, v in properties.items():
        expected = schema.get(k)
        if not _type_ok(expected, v):
            bad[k] = {"expected": expected, "got": type(v).__name__}
    if bad:
        usage = _ensure_usage_store()
        usage["counters"]["total_requests"] += 1
        usage["requests"].append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": "VALIDATION_ERROR",
                "ts": _now(),
                "ts_unix": time.time(),
                "latency_ms": int((time.time() - started) * 1000),
                "meta": {"invalid_types": bad},
            }
        )
        _save("usage_log.json", usage)
        return _err("VALIDATION_ERROR", "Invalid property types.", invalid_types=bad)

    # Rate limit check (record as blocked if exceeded)
    rl = _log_and_maybe_limit("blocked_rate_limit", started, endpoint, meta={"db_title": title})
    if rl:
        return rl

    # Create row with unique id
    existing_ids = {r.get("id") for r in db["rows"] if isinstance(r, dict)}
    while True:
        row_id = "row_" + uuid.uuid4().hex
        if row_id not in existing_ids:
            break
    row = {"id": row_id}
    for k, v in properties.items():
        row[k] = v
    # audit fields (not in schema, but harmless for storage)
    row["_created_at"] = _now()
    row["_updated_at"] = row["_created_at"]

    db["rows"].append(row)

    # Persist change
    _save("notion_databases.json", dbs)

    # Log usage
    usage = _ensure_usage_store()
    usage["counters"]["total_requests"] += 1
    usage["requests"].append(
        {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": "OK",
            "ts": _now(),
            "ts_unix": time.time(),
            "latency_ms": int((time.time() - started) * 1000),
            "meta": {"db_title": title, "database_id": db.get("id"), "row_id": row_id},
        }
    )
    _save("usage_log.json", usage)

    return {"object": "database_row", "database_id": db.get("id"), "row": row}

