        )
        _save("usage_log.json", usage)
        return _err("VALIDATION_ERROR", "Unknown properties provided.", unknown_properties=unknown)

    def _type_ok(expected, value):
        if expected is None:
            return True
        if not isinstance(expected, str):
            return True
        t = expected.lower()
        if t in ("text", "string", "title", "rich_text", "email", "url", "date"):
