        if t in ("number", "float", "double"):
            return value is None or isinstance(value, (int, float)) and not isinstance(value, bool)
        if t in ("integer", "int"):
            return value is None or (isinstance(value, int) and not isinstance(value, bool))
        if t in ("checkbox", "boolean", "bool"):
            return value is None or isinstance(value, bool)
        return True

    bad = {}
    for k, v in properties.items():
        expected = schema.get(k)
        if not _type_ok(expected, v):
            bad[k] = {"expected": expected, "got": type(v).__name__}
    if bad:
        usage = _ensure_usage_store()
        usage["counters"]["total_requests"] += 1
        usage["requests"].append(
            {"id": "req_" + uuid.uuid4().hex, "endpoint": endpoint, "status": "VALIDATION_ERROR", "ts": _now(), "ts_unix": time.time(), "latency_ms": int((time.time() - started) * 1000), "meta": {"invalid_types": bad, "page_id": pid}}
        )
        _save("usage_log.json", usage)
        return _err("VALIDATION_ERROR", "Invalid property types.", invalid_types=bad)

    # Apply updates
    changed = False
    for k, v in properties.items():
        if found_row.get(k) != v:
            found_row[k] = v
            changed = True

    if not changed:
        # idempotent: still a successful update with no material change, but it DID match a row.
        pass

    found_row["_updated_at"] = _now()

    _save("notion_databases.json", dbs)

    usage = _ensure_usage_store()
    usage["counters"]["total_requests"] += 1
    usage["requests"].append(
        {"id": "req_" + uuid.uuid4().hex, "endpoint": endpoint, "status": "OK", "ts": _now(), "ts_unix": time.time(), "latency_ms": int((time.time() - started) * 1000), "meta": {"page_id": pid, "database_id": found_db.get("id")}}
    )
    _save("usage_log.json", usage)

    return {"object": "database_row", "database_id": found_db.get("id"), "row": found_row}

