        usage["counters"]["total_requests"] += 1
        usage["requests"].append(
            {"id": "req_" + uuid.uuid4().hex, "endpoint": endpoint, "status": "VALIDATION_ERROR", "ts": _now(), "ts_unix": time.time(), "latency_ms": int((time.time() - started) * 1000)}
