def create_database(title, properties_schema, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0284000" if __import__("os").path.isdir("./environment_mix/0284000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_usage_store():
        usage = _load("usage_log.json")
        if not isinstance(usage, dict):
            usage = {}
        if "requests" not in usage or not isinstance(usage.get("requests"), list):
            usage["requests"] = []
        if "counters" not in usage or not isinstance(usage.get("counters"), dict):
            usage["counters"] = {}
        if "total_requests" not in usage["counters"]:
            usage["counters"]["total_requests"] = 0
        return usage

    started = time.time()
    endpoint = "create_database"

    if not isinstance(title, str) or not title.strip():
        usage = _ensure_usage_store()
        usage["counters"]["total_requests"] += 1
        usage["requests"].append(
            {"id": "req_" + uuid.uuid4().hex, "endpoint": endpoint, "status": "VALIDATION_ERROR", "ts": _now(), "ts_unix": time.time(), "latency_ms": int((time.time() - started) * 1000)}
        )
        _save("usage_log.json", usage)
        return _err("VALIDATION_ERROR", "title is required and must be a non-empty string.")
    if not isinstance(properties_schema, dict) or len(properties_schema) == 0:
        usage = _ensure_usage_store()
        usage["counters"]["total_requests"] += 1
        usage["requests"].append(
            {"id": "req_" + uuid.uuid4().hex, "endpoint": endpoint, "status": "VALIDATION_ERROR", "ts": _now(), "ts_unix": time.time(), "latency_ms": int((time.time() - started) * 1000)}
        )
        _save("usage_log.json", usage)
        return _err("VALIDATION_ERROR", "properties_schema is required and must be a non-empty object (dict).")

    # Validate schema mapping values as supported types
    supported = {
        "text",
        "string",
        "title",
        "rich_text",
        "number",
        "integer",
        "checkbox",
        "boolean",
        "email",
        "url",
        "date",
    }
    bad = {}
    for k, v in properties_schema.items():
        if not isinstance(k, str) or not k.strip():
            bad[str(k)] = "Property name must be a non-empty string."
            continue
        if not isinstance(v, str) or not v.strip():
            bad[k] = "Property type must be a non-empty string."
            continue
        if v.strip().lower() not in supported:
            bad[k] = f"Unsupported property type: {v}"
    if bad:
        usage = _ensure_usage_store()
        usage["counters"]["total_requests"] += 1
        usage["requests"].append(
            {"id": "req_" + uuid.uuid4().hex, "endpoint": endpoint, "status": "VALIDATION_ERROR", "ts": _now(), "ts_unix": time.time(), "latency_ms": int((time.time() - started) * 1000), "meta": {"schema_errors": bad}}
        )
        _save("usage_log.json", usage)
        return _err("VALIDATION_ERROR", "Invalid properties_schema.", schema_errors=bad)

    dbs = _load("notion_databases.json")
    if not isinstance(dbs, list):
        dbs = []

    t = title.strip()

    # Refuse ambiguous title conflicts (existing same title)
    if any(isinstance(d, dict) and d.get("title") == t for d in dbs):
        usage = _ensure_usage_store()
        usage["counters"]["total_requests"] += 1
        usage["requests"].append(
            {"id": "req_" + uuid.uuid4().hex, "endpoint": endpoint, "status": "CONFLICT", "ts": _now(), "ts_unix": time.time(), "latency_ms": int((time.time() - started) * 1000), "meta": {"title": t}}
        )
        _save("usage_log.json", usage)
        return _err("CONFLICT", "A database with this title already exists.", title=t)

    # Generate unique database id
    existing_ids = {d.get("id") for d in dbs if isinstance(d, dict)}
    while True:
        did = "db_" + uuid.uuid4().hex
        if did not in existing_ids:
            break

    schema_out = {str(k).strip(): str(v).strip() for k, v in properties_schema.items()}

    db = {"id": did, "title": t, "schema": schema_out, "rows": [], "_created_at": _now(), "_updated_at": _now()}
    dbs.append(db)
    _save("notion_databases.json", dbs)

    usage = _ensure_usage_store()
    usage["counters"]["total_requests"] += 1
    usage["requests"].append(
        {"id": "req_" + uuid.uuid4().hex, "endpoint": endpoint, "status": "OK", "ts": _now(), "ts_unix": time.time(), "latency_ms": int((time.time() - started) * 1000), "meta": {"database_id": did, "title": t}}
    )
    _save("usage_log.json", usage)

    return {"object": "database", "database": {"id": db["id"], "title": db["title"], "schema": db["schema"]}}
